// Core tests: the 19 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, and property cases from the
// SPEC's tests section. The extra success expectations below were derived
// independently with 50-digit Decimal arithmetic on the SPEC's pinned
// formula (a = 17.27, b = 237.7, es0 = 6.112, AH constant 216.7,
// r(x) = floor(x * 10 + 0.5) / 10, band from the rounded dew point).

import assert from "node:assert/strict";
import test from "node:test";
import { comfortBandFor, formatOneDecimal, run } from "../public/js/core/dew-point.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const base = { temperature: "25", relativeHumidity: "60" };

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

test("independently derived success cases", () => {
  // Leading zeros are allowed: "007" = 7 °C.
  assert.deepEqual(run({ temperature: "007", relativeHumidity: "60" }), {
    ok: true,
    result: { dewPointC: -0.2, absoluteHumidityGm3: 4.6, comfortBand: "dry" },
  });
  // RH = 100 at the cold endpoint: dew point equals the temperature.
  assert.deepEqual(run({ temperature: "-50", relativeHumidity: "100" }), {
    ok: true,
    result: { dewPointC: -50, absoluteHumidityGm3: 0.1, comfortBand: "dry" },
  });
  assert.deepEqual(run({ temperature: "0", relativeHumidity: "100" }), {
    ok: true,
    result: { dewPointC: 0, absoluteHumidityGm3: 4.8, comfortBand: "dry" },
  });
  // Very dry hot air at the temperature ceiling.
  assert.deepEqual(run({ temperature: "60", relativeHumidity: "0.5" }), {
    ok: true,
    result: { dewPointC: -22.6, absoluteHumidityGm3: 0.6, comfortBand: "dry" },
  });
  // Just below saturation rounds to the temperature itself.
  assert.deepEqual(run({ temperature: "25", relativeHumidity: "99.9" }), {
    ok: true,
    result: { dewPointC: 25, absoluteHumidityGm3: 23, comfortBand: "extremely-oppressive" },
  });
  assert.deepEqual(run({ temperature: "-0.5", relativeHumidity: "50" }), {
    ok: true,
    result: { dewPointC: -9.6, absoluteHumidityGm3: 2.3, comfortBand: "dry" },
  });
  assert.deepEqual(run({ temperature: "33.3", relativeHumidity: "33.3" }), {
    ok: true,
    result: { dewPointC: 15, absoluteHumidityGm3: 12, comfortBand: "mostly-comfortable" },
  });
});

test("grammar: signs, dots, spaces, exponents and separators are DECIMAL_FORMAT", () => {
  const expected = { code: "DECIMAL_FORMAT", field: "temperature", row: null };
  for (const bad of ["+25", "25.", ".5", " 25", "25 ", "1e3", "25,5", "-", "--5", "2 5", "２５"]) {
    assert.deepEqual(errorOf({ ...base, temperature: bad }), expected, `temperature ${JSON.stringify(bad)}`);
  }
  assert.deepEqual(errorOf({ ...base, relativeHumidity: "60%" }), {
    code: "DECIMAL_FORMAT",
    field: "relativeHumidity",
    row: null,
  });
});

test("capacity is checked before grammar: a 9-unit value is INPUT_LIMIT", () => {
  assert.deepEqual(errorOf({ ...base, temperature: "12345678." }), {
    code: "INPUT_LIMIT",
    field: "temperature",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, relativeHumidity: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "relativeHumidity",
    row: null,
  });
});

test("an empty field is EMPTY; a lone surrogate is UNICODE; a paired surrogate is grammar", () => {
  assert.deepEqual(errorOf({ ...base, temperature: "" }), {
    code: "EMPTY",
    field: "temperature",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, temperature: "\uD800" }), {
    code: "UNICODE",
    field: "temperature",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, relativeHumidity: "\uDC00" }), {
    code: "UNICODE",
    field: "relativeHumidity",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, temperature: "\uD83D\uDE00" }), {
    code: "DECIMAL_FORMAT",
    field: "temperature",
    row: null,
  });
});

test("range boundaries: endpoints valid, just outside is RANGE", () => {
  assert.equal(run({ temperature: "-50", relativeHumidity: "60" }).ok, true);
  assert.equal(run({ temperature: "60", relativeHumidity: "60" }).ok, true);
  assert.equal(run({ temperature: "25", relativeHumidity: "100" }).ok, true);
  assert.equal(run({ temperature: "25", relativeHumidity: "100.0" }).ok, true);
  assert.equal(run({ temperature: "25", relativeHumidity: "0.1" }).ok, true);
  assert.deepEqual(errorOf({ ...base, temperature: "-50.1" }), {
    code: "RANGE",
    field: "temperature",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, temperature: "60.1" }), {
    code: "RANGE",
    field: "temperature",
    row: null,
  });
  // RH = 0 in any spelling is RANGE (the ln-domain guard), never computed.
  for (const zero of ["0", "0.0", "-0", "-5"]) {
    assert.deepEqual(errorOf({ ...base, relativeHumidity: zero }), {
      code: "RANGE",
      field: "relativeHumidity",
      row: null,
    }, `relativeHumidity ${zero}`);
  }
});

test("the first field in the fixed order reports first", () => {
  assert.deepEqual(errorOf({ temperature: "61", relativeHumidity: "0" }), {
    code: "RANGE",
    field: "temperature",
    row: null,
  });
  assert.deepEqual(errorOf({ temperature: "25..5", relativeHumidity: "" }), {
    code: "DECIMAL_FORMAT",
    field: "temperature",
    row: null,
  });
});

test("schema: extra key, missing key, wrong type, array, null, and accessor are all SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ ...base, extra: "1" }), schema);
  const missing = { ...base };
  delete missing.relativeHumidity;
  assert.deepEqual(errorOf(missing), schema);
  assert.deepEqual(errorOf({ ...base, temperature: 25 }), schema);
  assert.deepEqual(errorOf(["25", "60"]), schema);
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("25"), schema);
  const withGetter = { ...base };
  Object.defineProperty(withGetter, "temperature", {
    enumerable: true,
    get() {
      return "25";
    },
  });
  assert.deepEqual(errorOf(withGetter), schema);
});

test("property: dew point never exceeds the temperature, with equality iff RH = 100", () => {
  const inputs = [
    ["25", "60"],
    ["25", "100"],
    ["-10", "80"],
    ["40", "10"],
    ["0", "1"],
    ["60", "100"],
    ["-50", "99"],
    ["15.5", "33.3"],
  ];
  for (const [temperature, relativeHumidity] of inputs) {
    const outcome = run({ temperature, relativeHumidity });
    assert.equal(outcome.ok, true);
    assert.ok(
      outcome.result.dewPointC <= Number(temperature),
      `${temperature}/${relativeHumidity}: dew point above temperature`,
    );
    if (relativeHumidity === "100") {
      assert.equal(outcome.result.dewPointC, Number(temperature));
    }
  }
});

test("property: at fixed temperature, dew point and absolute humidity strictly increase with RH", () => {
  let previous = null;
  for (const relativeHumidity of ["10", "30", "50", "70", "90"]) {
    const outcome = run({ temperature: "25", relativeHumidity });
    assert.equal(outcome.ok, true);
    if (previous !== null) {
      assert.ok(outcome.result.dewPointC > previous.dewPointC);
      assert.ok(outcome.result.absoluteHumidityGm3 > previous.absoluteHumidityGm3);
    }
    previous = outcome.result;
  }
});

test("comfort band boundaries are taken from the rounded dew point", () => {
  const cases = [
    [9.9, "dry"],
    [10.0, "comfortable"],
    [12.9, "comfortable"],
    [13.0, "mostly-comfortable"],
    [15.9, "mostly-comfortable"],
    [16.0, "slightly-humid"],
    [17.9, "slightly-humid"],
    [18.0, "humid"],
    [20.9, "humid"],
    [21.0, "oppressive"],
    [23.9, "oppressive"],
    [24.0, "extremely-oppressive"],
    [-55.8, "dry"],
    [60.0, "extremely-oppressive"],
  ];
  for (const [value, band] of cases) {
    assert.equal(comfortBandFor(value), band, `band for ${value}`);
  }
});

test("display formatting always shows exactly one decimal", () => {
  assert.equal(formatOneDecimal(20), "20.0");
  assert.equal(formatOneDecimal(0), "0.0");
  assert.equal(formatOneDecimal(-11.1), "-11.1");
  assert.equal(formatOneDecimal(129.1), "129.1");
});
